//! Runtime schema: comptime reflection turned into descriptors that data-driven
//! code can walk (design doc section 12).
//!
//! `typeOf(T)` reflects a struct (or any supported type) once, at compile time,
//! into a constant `Type` tree: field names, kinds, nested types, enum names,
//! which dirty categories a change needs (from a `dirty_map` decl, as the shadow
//! checker uses), and optional presentation metadata (from a `ui` decl, as in
//! design doc section 11). Each type also carries typed get/set functions that
//! were generated by the compiler, so reading and writing a field through the
//! schema is ordinary type-checked Zig, not raw memory access.
//!
//! The consumers are the builder's inspector, form generation, serialization,
//! and the future C facade. The engine only ever consumes the runtime form.
//!
//! Supported leaves: bool, integers, floats, enums, `Color`, `Length`, the
//! toolkit's text wrapper (anything declaring `is_text`), and `[]const u8`
//! strings (read-only). Structs, optionals, and fixed arrays nest. Callbacks
//! (`is_callback`, function pointers) are listed but not editable. Anything
//! else is listed as `.unsupported`.
//!
//! Paths address nested values: `"colors.normal"`, `"syntax[3]"`,
//! `"colors.syntax[3].r"`. Navigating into an absent optional is an error;
//! `isPresent`, `setAbsent`, and `setPresentFrom` manage presence.
//!
//! Optional field metadata, per field:
//!
//!     pub const ui = .{
//!         .size = .{ .label = "Font size", .min = 0, .max = 200, .tooltip = "0 = theme size" },
//!     };

const std = @import("std");
const geometry = @import("geometry.zig");
const Color = geometry.Color;
const Length = @import("length.zig").Length;
const shadow = @import("shadow.zig");
const DirtyFlags = @import("dirty.zig").DirtyFlags;

pub const Error = error{
    UnknownField,
    BadPath,
    NotALeaf,
    TypeMismatch,
    OutOfRange,
    NotPresent,
    ReadOnly,
    OutOfMemory,
};

pub const Kind = enum { bool, int, float, choice, string, text, color, length, @"struct", optional, array, callback, unsupported };

/// A leaf value. Absent optionals read as `.none`; writing `.none` clears one.
pub const Value = union(enum) {
    none,
    bool: bool,
    int: i64,
    float: f64,
    /// Index into the enum's `enum_names`.
    choice: u32,
    /// Borrowed text (reads), or the bytes to copy (writes).
    text: []const u8,
    color: Color,
    length: Length,
};

pub fn valueEql(a: Value, b: Value) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .none => true,
        .bool => |x| x == b.bool,
        .int => |x| x == b.int,
        .float => |x| x == b.float,
        .choice => |x| x == b.choice,
        .text => |x| std.mem.eql(u8, x, b.text),
        .color => |x| std.meta.eql(x, b.color),
        .length => |x| std.meta.eql(x, b.length),
    };
}

/// What a setter needs from its owner. Text fields are toolkit-owned memory,
/// so writing one must go through whoever owns the allocator.
pub const Env = struct {
    ctx: ?*anyopaque = null,
    /// Replace a text wrapper's contents with a copy of `bytes`. `text_ptr`
    /// points at the wrapper (a `Text`).
    replace_text: ?*const fn (ctx: ?*anyopaque, text_ptr: *anyopaque, bytes: []const u8) error{OutOfMemory}!void = null,
    /// Replace a plain `[]const u8` field's contents with a copy of `bytes`.
    /// `slot` points at the slice. Without this hook, string fields are read-only.
    replace_string: ?*const fn (ctx: ?*anyopaque, slot: *[]const u8, bytes: []const u8) error{OutOfMemory}!void = null,
};

/// Presentation hints for editors and form generators.
pub const Meta = struct {
    label: ?[]const u8 = null,
    tooltip: ?[]const u8 = null,
    min: ?f64 = null,
    max: ?f64 = null,
    step: ?f64 = null,
    group: ?[]const u8 = null,
    multiline: bool = false,
    /// Not shown in inspectors.
    hidden: bool = false,
    readonly: bool = false,
};

pub const Field = struct {
    name: []const u8,
    type: *const Type,
    /// Byte offset within the parent struct.
    offset: usize,
    /// What changing this field requires (from the owner's `dirty_map`; layout
    /// and paint when unlisted, the always-safe default).
    dirty: DirtyFlags,
    meta: Meta,

    /// `snake_case` as "Snake case", or the `meta.label` if set.
    pub fn displayName(self: Field, buf: []u8) []const u8 {
        if (self.meta.label) |l| return l;
        const n = @min(self.name.len, buf.len);
        for (self.name[0..n], 0..) |c, i| {
            buf[i] = if (c == '_') ' ' else if (i == 0) std.ascii.toUpper(c) else c;
        }
        return buf[0..n];
    }
};

pub const Type = struct {
    kind: Kind,
    /// The Zig type's name, for display and debugging.
    name: []const u8,
    // int and float
    signed: bool = false,
    bits: u16 = 0,
    // choice
    enum_names: []const []const u8 = &.{},
    // optional (payload) and array (element)
    child: ?*const Type = null,
    len: usize = 0,
    elem_size: usize = 0,
    // struct
    fields: []const Field = &.{},

    get: ?*const fn (p: *const anyopaque) Value = null,
    set: ?*const fn (p: *anyopaque, v: Value, env: *const Env) Error!void = null,
    // optional only
    payload: ?*const fn (p: *anyopaque) ?*anyopaque = null,
    set_absent: ?*const fn (p: *anyopaque) void = null,
    set_present_from: ?*const fn (p: *anyopaque, template: *const anyopaque) void = null,
    /// optional only: the payload type's default value (see `defaultOf`).
    payload_default: ?*const anyopaque = null,

    pub fn field(self: *const Type, name: []const u8) ?*const Field {
        for (self.fields) |*f| if (std.mem.eql(u8, f.name, name)) return f;
        return null;
    }

    pub fn isLeaf(self: *const Type) bool {
        return switch (self.kind) {
            .bool, .int, .float, .choice, .string, .text, .color, .length => true,
            .optional => self.child.?.isLeaf(),
            else => false,
        };
    }

    /// True for fields a user may edit through the schema.
    pub fn isEditable(self: *const Type) bool {
        return switch (self.kind) {
            .callback, .unsupported => false,
            .optional => self.child.?.isEditable(),
            else => true,
        };
    }
};

// ---- reflection ------------------------------------------------------------

/// The schema of `T`, built once at compile time.
pub fn typeOf(comptime T: type) *const Type {
    const Holder = struct {
        const value: Type = build(T);
    };
    return &Holder.value;
}

fn isText(comptime T: type) bool {
    return @typeInfo(T) == .@"struct" and @hasDecl(T, "is_text");
}

fn isCallbackType(comptime T: type) bool {
    return switch (@typeInfo(T)) {
        .pointer => |p| @typeInfo(p.child) == .@"fn",
        .@"struct" => @hasDecl(T, "is_callback"),
        else => false,
    };
}

fn metaFor(comptime T: type, comptime name: []const u8) Meta {
    var m: Meta = .{};
    if (@typeInfo(T) == .@"struct" and @hasDecl(T, "ui")) {
        const all = T.ui;
        if (@hasField(@TypeOf(all), name)) {
            const entry = @field(all, name);
            inline for (@typeInfo(@TypeOf(entry)).@"struct".field_names) |fname| {
                if (@hasField(Meta, fname)) @field(m, fname) = @field(entry, fname);
            }
        }
    }
    return m;
}

fn Access(comptime T: type) type {
    return struct {
        fn get(p: *const anyopaque) Value {
            const x: *const T = @ptrCast(@alignCast(p));
            return toValue(T, x.*);
        }
        fn set(p: *anyopaque, v: Value, env: *const Env) Error!void {
            const x: *T = @ptrCast(@alignCast(p));
            try assign(T, x, v, env);
        }
    };
}

fn OptionalAccess(comptime T: type) type {
    const C = @typeInfo(T).optional.child;
    return struct {
        fn payload(p: *anyopaque) ?*anyopaque {
            const x: *T = @ptrCast(@alignCast(p));
            if (x.*) |*inner| return @ptrCast(inner);
            return null;
        }
        const default: C = defaultOf(C);
        fn setAbsent(p: *anyopaque) void {
            const x: *T = @ptrCast(@alignCast(p));
            x.* = null;
        }
        fn setPresentFrom(p: *anyopaque, template: *const anyopaque) void {
            const x: *T = @ptrCast(@alignCast(p));
            const t: *const C = @ptrCast(@alignCast(template));
            x.* = t.*;
        }
    };
}

fn build(comptime T: type) Type {
    const A = Access(T);
    const name = @typeName(T);
    switch (@typeInfo(T)) {
        .bool => return .{ .kind = .bool, .name = name, .get = A.get, .set = A.set },
        .int => |i| return .{ .kind = .int, .name = name, .signed = i.signedness == .signed, .bits = i.bits, .get = A.get, .set = A.set },
        .float => |f| return .{ .kind = .float, .name = name, .bits = f.bits, .get = A.get, .set = A.set },
        .@"enum" => |e| {
            const names = comptime blk: {
                var arr: [e.field_names.len][]const u8 = undefined;
                for (e.field_names, 0..) |n, i| arr[i] = n;
                break :blk arr;
            };
            return .{ .kind = .choice, .name = name, .enum_names = &names, .get = A.get, .set = A.set };
        },
        .optional => {
            const C = @typeInfo(T).optional.child;
            if (comptime isCallbackType(C)) return .{ .kind = .callback, .name = name };
            const O = OptionalAccess(T);
            return .{
                .kind = .optional,
                .name = name,
                .child = typeOf(C),
                .get = A.get,
                .set = A.set,
                .payload = O.payload,
                .set_absent = O.setAbsent,
                .set_present_from = O.setPresentFrom,
                .payload_default = &O.default,
            };
        },
        .array => |a| return .{
            .kind = .array,
            .name = name,
            .child = typeOf(a.child),
            .len = a.len,
            .elem_size = @sizeOf(a.child),
        },
        .pointer => |p| {
            if (@typeInfo(p.child) == .@"fn") return .{ .kind = .callback, .name = name };
            if (p.size == .slice and p.child == u8) return .{ .kind = .string, .name = name, .get = A.get, .set = A.set };
            return .{ .kind = .unsupported, .name = name };
        },
        .@"union" => {
            if (T == Length) return .{ .kind = .length, .name = name, .get = A.get, .set = A.set };
            return .{ .kind = .unsupported, .name = name };
        },
        .@"struct" => |s| {
            if (T == Color) return .{ .kind = .color, .name = name, .get = A.get, .set = A.set };
            if (comptime isText(T)) return .{ .kind = .text, .name = name, .get = A.get, .set = A.set };
            if (comptime isCallbackType(T)) return .{ .kind = .callback, .name = name };
            const fields = comptime blk: {
                var arr: [s.field_names.len]Field = undefined;
                for (s.field_names, s.field_types, 0..) |fname, FT, i| {
                    arr[i] = .{
                        .name = fname,
                        .type = typeOf(FT),
                        .offset = @offsetOf(T, fname),
                        .dirty = if (@hasDecl(T, "dirty_map")) shadow.requiredFor(T, fname) else DirtyFlags.layout_and_paint,
                        .meta = metaFor(T, fname),
                    };
                }
                break :blk arr;
            };
            return .{ .kind = .@"struct", .name = name, .fields = &fields };
        },
        else => return .{ .kind = .unsupported, .name = name },
    }
}

fn toValue(comptime T: type, x: T) Value {
    switch (@typeInfo(T)) {
        .bool => return .{ .bool = x },
        .int => return .{ .int = @intCast(x) },
        .float => return .{ .float = @floatCast(x) },
        .@"enum" => |e| {
            inline for (e.field_values, 0..) |val, i| {
                if (@intFromEnum(x) == val) return .{ .choice = @intCast(i) };
            }
            unreachable;
        },
        .optional => if (x) |inner| return toValue(@typeInfo(T).optional.child, inner) else return .none,
        .pointer => |p| {
            if (p.size == .slice and p.child == u8) return .{ .text = x };
            return .none;
        },
        .@"union" => if (T == Length) return .{ .length = x } else return .none,
        .@"struct" => {
            if (T == Color) return .{ .color = x };
            if (comptime isText(T)) return .{ .text = x.bytes };
            return .none;
        },
        else => return .none,
    }
}

fn fromValue(comptime T: type, v: Value) Error!T {
    switch (@typeInfo(T)) {
        .bool => return switch (v) {
            .bool => |b| b,
            else => error.TypeMismatch,
        },
        .int => return switch (v) {
            .int => |i| std.math.cast(T, i) orelse error.OutOfRange,
            else => error.TypeMismatch,
        },
        .float => return switch (v) {
            .float => |f| @floatCast(f),
            .int => |i| @floatFromInt(i),
            else => error.TypeMismatch,
        },
        .@"enum" => |e| switch (v) {
            .choice => |idx| {
                inline for (e.field_values, 0..) |val, i| {
                    if (i == idx) return @enumFromInt(val);
                }
                return error.OutOfRange;
            },
            else => return error.TypeMismatch,
        },
        .@"union" => {
            if (T == Length) return switch (v) {
                .length => |l| l,
                else => error.TypeMismatch,
            };
            return error.TypeMismatch;
        },
        .@"struct" => {
            if (T == Color) return switch (v) {
                .color => |c| c,
                else => error.TypeMismatch,
            };
            return error.TypeMismatch;
        },
        else => return error.TypeMismatch,
    }
}

fn assign(comptime T: type, ptr: *T, v: Value, env: *const Env) Error!void {
    switch (@typeInfo(T)) {
        .optional => |o| {
            if (v == .none) {
                ptr.* = null;
                return;
            }
            // Scalars and wrappers: write the payload. (Optional structs are
            // edited field by field through a path once present.)
            var tmp: o.child = undefined;
            if (ptr.*) |cur| tmp = cur;
            try assign(o.child, &tmp, v, env);
            ptr.* = tmp;
        },
        .pointer => |p| {
            if (p.size == .slice and p.child == u8) {
                const f = env.replace_string orelse return error.ReadOnly;
                return switch (v) {
                    .text => |bytes| f(env.ctx, @ptrCast(ptr), bytes),
                    else => error.TypeMismatch,
                };
            }
            return error.ReadOnly;
        },
        .@"struct" => {
            if (comptime isText(T)) {
                const f = env.replace_text orelse return error.ReadOnly;
                return switch (v) {
                    .text => |bytes| f(env.ctx, @ptrCast(ptr), bytes),
                    else => error.TypeMismatch,
                };
            }
            ptr.* = try fromValue(T, v);
        },
        else => ptr.* = try fromValue(T, v),
    }
}

/// A value of `T` built from field defaults; fields without one get the zero
/// value of their type (first tag for enums, `null` for optionals, empty for
/// strings). Used to make absent optionals present.
pub fn defaultOf(comptime T: type) T {
    switch (@typeInfo(T)) {
        .bool => return false,
        .int => return 0,
        .float => return 0,
        .@"enum" => |e| return @enumFromInt(e.field_values[0]),
        .optional => return null,
        .array => |a| return @splat(defaultOf(a.child)),
        .pointer => |p| {
            if (p.size == .slice and p.child == u8) return "";
            if (@typeInfo(p.child) == .@"fn") return undefined;
            return undefined;
        },
        .@"union" => |u| {
            if (T == Length) return .auto;
            return @unionInit(T, u.field_names[0], defaultOf(u.field_types[0]));
        },
        .@"struct" => |s| {
            var out: T = undefined;
            inline for (s.field_names, s.field_types, s.field_attrs) |n, FT, attrs| {
                // Plain pointers have no meaningful default; leave them unset.
                if (comptime @typeInfo(FT) == .pointer and @typeInfo(FT).pointer.size != .slice) continue;
                @field(out, n) = attrs.defaultValue(FT) orelse defaultOf(FT);
            }
            return out;
        },
        .void => return {},
        else => return undefined,
    }
}

// ---- paths ---------------------------------------------------------------------

pub const Resolved = struct {
    /// The type at the end of the path (an optional stays an optional here).
    ty: *const Type,
    ptr: *anyopaque,
    /// The first field on the path: what the dirty category comes from.
    top: *const Field,
};

fn parseIndex(seg: []const u8) Error!struct { name: []const u8, indices: []const u8 } {
    const open = std.mem.indexOfScalar(u8, seg, '[') orelse return .{ .name = seg, .indices = "" };
    return .{ .name = seg[0..open], .indices = seg[open..] };
}

/// Walk `path` from a struct value. See the module docs for the syntax.
pub fn resolve(root: *const Type, base: *anyopaque, path: []const u8) Error!Resolved {
    if (root.kind != .@"struct") return error.BadPath;
    var ty = root;
    var ptr = base;
    var top: ?*const Field = null;

    var segs = std.mem.splitScalar(u8, path, '.');
    while (segs.next()) |seg| {
        if (seg.len == 0) return error.BadPath;
        // Step into the struct that owns this segment.
        while (ty.kind == .optional) {
            ptr = ty.payload.?(ptr) orelse return error.NotPresent;
            ty = ty.child.?;
        }
        if (ty.kind != .@"struct") return error.BadPath;
        const parsed = try parseIndex(seg);
        const f = ty.field(parsed.name) orelse return error.UnknownField;
        if (top == null) top = f;
        ptr = @ptrFromInt(@intFromPtr(ptr) + f.offset);
        ty = f.type;

        var idx = parsed.indices;
        while (idx.len > 0) {
            if (idx[0] != '[') return error.BadPath;
            const close = std.mem.indexOfScalar(u8, idx, ']') orelse return error.BadPath;
            const n = std.fmt.parseInt(usize, idx[1..close], 10) catch return error.BadPath;
            while (ty.kind == .optional) {
                ptr = ty.payload.?(ptr) orelse return error.NotPresent;
                ty = ty.child.?;
            }
            if (ty.kind != .array) return error.BadPath;
            if (n >= ty.len) return error.OutOfRange;
            ptr = @ptrFromInt(@intFromPtr(ptr) + n * ty.elem_size);
            ty = ty.child.?;
            idx = idx[close + 1 ..];
        }
    }
    return .{ .ty = ty, .ptr = ptr, .top = top orelse return error.BadPath };
}

/// Read a leaf by path.
pub fn get(root: *const Type, base: *anyopaque, path: []const u8) Error!Value {
    const r = try resolve(root, base, path);
    if (!r.ty.isLeaf() and r.ty.kind != .callback) return error.NotALeaf;
    const f = r.ty.get orelse return .none;
    return f(r.ptr);
}

/// Write a leaf by path. The caller marks `top.dirty` (see `topField`).
pub fn set(root: *const Type, base: *anyopaque, path: []const u8, v: Value, env: *const Env) Error!void {
    const r = try resolve(root, base, path);
    if (!r.ty.isLeaf()) return if (r.ty.isEditable()) error.NotALeaf else error.ReadOnly;
    if (r.top.meta.readonly) return error.ReadOnly;
    const f = r.ty.set orelse return error.ReadOnly;
    try f(r.ptr, v, env);
}

/// The first field of `path`, without needing a value (for its dirty category).
pub fn topField(root: *const Type, path: []const u8) Error!*const Field {
    var segs = std.mem.splitScalar(u8, path, '.');
    const first = segs.next() orelse return error.BadPath;
    const parsed = try parseIndex(first);
    return root.field(parsed.name) orelse error.UnknownField;
}

/// Make the optional at `path` present with its payload type's default value.
pub fn setPresentDefault(root: *const Type, base: *anyopaque, path: []const u8) Error!void {
    const r = try resolve(root, base, path);
    if (r.ty.kind != .optional) return error.TypeMismatch;
    r.ty.set_present_from.?(r.ptr, r.ty.payload_default.?);
}

/// Whether the optional at `path` has a value.
pub fn isPresent(root: *const Type, base: *anyopaque, path: []const u8) Error!bool {
    const r = try resolve(root, base, path);
    if (r.ty.kind != .optional) return error.TypeMismatch;
    return r.ty.payload.?(r.ptr) != null;
}

/// Clear the optional at `path`.
pub fn setAbsent(root: *const Type, base: *anyopaque, path: []const u8) Error!void {
    const r = try resolve(root, base, path);
    if (r.ty.kind != .optional) return error.TypeMismatch;
    r.ty.set_absent.?(r.ptr);
}

/// Make the optional at `path` present, as a copy of `template` (a pointer to a
/// value of the payload type).
pub fn setPresentFrom(root: *const Type, base: *anyopaque, path: []const u8, template: *const anyopaque) Error!void {
    const r = try resolve(root, base, path);
    if (r.ty.kind != .optional) return error.TypeMismatch;
    r.ty.set_present_from.?(r.ptr, template);
}

// ---- tests -----------------------------------------------------------------

const testing = std.testing;

const Mode = enum { off, on, auto };
const Tag = enum(u8) { a = 3, b = 7, c = 9 };

const Palette = struct {
    bg: Color,
    fg: Color,
    accents: [3]Color = @splat(Color.black),
};

const DemoText = struct {
    bytes: []const u8 = "",
    pub const is_text = true;
};

const Probe = struct {
    flag: bool = false,
    count: u8 = 3,
    signed: i16 = -5,
    ratio: f32 = 0.5,
    mode: Mode = .auto,
    sparse: Tag = .b,
    tint: Color = Color.white,
    width: Length = .auto,
    label: DemoText = .{},
    note: []const u8 = "note",
    limit: ?u32 = null,
    palette: ?Palette = null,
    on_event: ?*const fn () void = null,
    raw: *u8 = undefined,

    pub const dirty_map = .{
        .count = shadow.Category.layout,
        .tint = shadow.Category.paint,
    };

    pub const ui = .{
        .count = .{ .label = "How many", .min = 1, .max = 9, .tooltip = "between one and nine" },
        .ratio = .{ .step = 0.25, .group = "Look" },
        .note = .{ .multiline = true },
        .flag = .{ .readonly = true },
    };
};

fn replaceTextTest(_: ?*anyopaque, ptr: *anyopaque, bytes: []const u8) error{OutOfMemory}!void {
    const t: *DemoText = @ptrCast(@alignCast(ptr));
    t.bytes = bytes; // test storage outlives the call
}

const test_env: Env = .{ .replace_text = replaceTextTest };

fn rootOf(p: *Probe) struct { *const Type, *anyopaque } {
    return .{ typeOf(Probe), @ptrCast(p) };
}

test "reflection lists fields with kinds, offsets, and names" {
    const t = typeOf(Probe);
    try testing.expectEqual(Kind.@"struct", t.kind);
    const kinds = [_]struct { name: []const u8, kind: Kind }{
        .{ .name = "flag", .kind = .bool },
        .{ .name = "count", .kind = .int },
        .{ .name = "signed", .kind = .int },
        .{ .name = "ratio", .kind = .float },
        .{ .name = "mode", .kind = .choice },
        .{ .name = "tint", .kind = .color },
        .{ .name = "width", .kind = .length },
        .{ .name = "label", .kind = .text },
        .{ .name = "note", .kind = .string },
        .{ .name = "limit", .kind = .optional },
        .{ .name = "palette", .kind = .optional },
        .{ .name = "on_event", .kind = .callback },
        .{ .name = "raw", .kind = .unsupported },
    };
    for (kinds) |k| try testing.expectEqual(k.kind, t.field(k.name).?.type.kind);
    try testing.expect(t.field("nope") == null);
    try testing.expect(t.field("count").?.offset == @offsetOf(Probe, "count"));
    const count = t.field("count").?.type;
    try testing.expect(!count.signed and count.bits == 8);
    try testing.expect(t.field("signed").?.type.signed);
}

test "enum names and values map by index, including sparse values" {
    const mode = typeOf(Probe).field("mode").?.type;
    try testing.expectEqual(@as(usize, 3), mode.enum_names.len);
    try testing.expectEqualStrings("auto", mode.enum_names[2]);
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try testing.expectEqual(Value{ .choice = 2 }, try get(root, base, "mode"));
    try set(root, base, "mode", .{ .choice = 0 }, &test_env);
    try testing.expectEqual(Mode.off, p.mode);
    try testing.expectError(error.OutOfRange, set(root, base, "mode", .{ .choice = 3 }, &test_env));
    // Tag has values 3, 7, 9: the schema index is the position, not the value.
    try testing.expectEqual(Value{ .choice = 1 }, try get(root, base, "sparse"));
    try set(root, base, "sparse", .{ .choice = 2 }, &test_env);
    try testing.expectEqual(Tag.c, p.sparse);
}

test "scalars round-trip, with range and type errors" {
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try set(root, base, "count", .{ .int = 200 }, &test_env);
    try testing.expectEqual(@as(u8, 200), p.count);
    try testing.expectError(error.OutOfRange, set(root, base, "count", .{ .int = 300 }, &test_env));
    try testing.expectError(error.OutOfRange, set(root, base, "count", .{ .int = -1 }, &test_env));
    try set(root, base, "signed", .{ .int = -32768 }, &test_env);
    try testing.expectEqual(@as(i16, -32768), p.signed);
    try testing.expectError(error.TypeMismatch, set(root, base, "count", .{ .float = 1.5 }, &test_env));
    try set(root, base, "ratio", .{ .float = 2.25 }, &test_env);
    try set(root, base, "ratio", .{ .int = 3 }, &test_env); // ints are accepted for floats
    try testing.expectEqual(@as(f32, 3), p.ratio);
    try testing.expectEqual(Value{ .float = 3 }, try get(root, base, "ratio"));
    try set(root, base, "tint", .{ .color = Color.rgb(1, 2, 3) }, &test_env);
    try testing.expectEqual(Color.rgb(1, 2, 3), p.tint);
    try set(root, base, "width", .{ .length = .px(40) }, &test_env);
    try testing.expectEqual(@as(f32, 40), p.width.pixels);
    try testing.expectEqual(Value{ .length = .{ .pixels = 40 } }, try get(root, base, "width"));
}

test "text goes through the owner's allocator hook; strings and callbacks are read-only" {
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try set(root, base, "label", .{ .text = "hello" }, &test_env);
    try testing.expectEqualStrings("hello", p.label.bytes);
    try testing.expectEqualStrings("hello", (try get(root, base, "label")).text);
    try testing.expectError(error.ReadOnly, set(root, base, "label", .{ .text = "x" }, &.{})); // no hook
    try testing.expectError(error.TypeMismatch, set(root, base, "label", .{ .int = 1 }, &test_env));
    try testing.expectEqualStrings("note", (try get(root, base, "note")).text);
    try testing.expectError(error.ReadOnly, set(root, base, "note", .{ .text = "x" }, &test_env));
    try testing.expectEqual(Value.none, try get(root, base, "on_event"));
    try testing.expectError(error.ReadOnly, set(root, base, "on_event", .none, &test_env));
    try testing.expect(!typeOf(Probe).field("on_event").?.type.isEditable());
    try testing.expect(typeOf(Probe).field("count").?.type.isEditable());
}

test "optional scalars: none clears, a value sets" {
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try testing.expectEqual(Value.none, try get(root, base, "limit"));
    try set(root, base, "limit", .{ .int = 12 }, &test_env);
    try testing.expectEqual(@as(?u32, 12), p.limit);
    try testing.expectEqual(Value{ .int = 12 }, try get(root, base, "limit"));
    try set(root, base, "limit", .none, &test_env);
    try testing.expectEqual(@as(?u32, null), p.limit);
    try testing.expect(try isPresent(root, base, "limit") == false);
}

test "optional structs: absent blocks navigation until made present from a template" {
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try testing.expect(!try isPresent(root, base, "palette"));
    try testing.expectError(error.NotPresent, get(root, base, "palette.bg"));
    try testing.expectError(error.NotPresent, set(root, base, "palette.bg", .{ .color = Color.black }, &test_env));

    const tmpl: Palette = .{ .bg = Color.rgb(9, 9, 9), .fg = Color.white };
    try setPresentFrom(root, base, "palette", &tmpl);
    try testing.expect(try isPresent(root, base, "palette"));
    try testing.expectEqual(Color.rgb(9, 9, 9), (try get(root, base, "palette.bg")).color);
    try set(root, base, "palette.fg", .{ .color = Color.rgb(5, 6, 7) }, &test_env);
    try testing.expectEqual(Color.rgb(5, 6, 7), p.palette.?.fg);

    try setAbsent(root, base, "palette");
    try testing.expect(p.palette == null);
    try testing.expectError(error.TypeMismatch, isPresent(root, base, "count")); // not an optional
}

test "arrays index with [n], and nested leaves chain" {
    var p: Probe = .{};
    p.palette = .{ .bg = Color.black, .fg = Color.white };
    const root, const base = rootOf(&p);
    try set(root, base, "palette.accents[2]", .{ .color = Color.rgb(1, 1, 1) }, &test_env);
    try testing.expectEqual(Color.rgb(1, 1, 1), p.palette.?.accents[2]);
    try testing.expectEqual(Color.rgb(1, 1, 1), (try get(root, base, "palette.accents[2]")).color);
    try testing.expectEqual(Color.black, (try get(root, base, "palette.accents[0]")).color);
    try testing.expectError(error.OutOfRange, get(root, base, "palette.accents[3]"));
    try testing.expectError(error.BadPath, get(root, base, "palette.accents[x]"));
    try testing.expectError(error.BadPath, get(root, base, "palette.accents[1"));
    try testing.expectError(error.NotALeaf, get(root, base, "palette.accents"));
    try testing.expectError(error.NotALeaf, get(root, base, "palette"));
    try testing.expectEqual(@as(u8, 1), (try get(root, base, "palette.accents[2]")).color.r);
}

fn replaceStringTest(_: ?*anyopaque, slot: *[]const u8, bytes: []const u8) error{OutOfMemory}!void {
    slot.* = bytes;
}

test "plain strings write only through the replace_string hook" {
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try testing.expectError(error.ReadOnly, set(root, base, "note", .{ .text = "x" }, &test_env));
    const e: Env = .{ .replace_string = replaceStringTest };
    try set(root, base, "note", .{ .text = "changed" }, &e);
    try testing.expectEqualStrings("changed", p.note);
    try testing.expectError(error.TypeMismatch, set(root, base, "note", .{ .int = 1 }, &e));
}

test "defaultOf honors field defaults and zeroes the rest" {
    const d = defaultOf(Palette);
    try testing.expectEqual(Color.black, d.accents[1]);
    const q = defaultOf(Probe);
    try testing.expectEqual(@as(u8, 3), q.count);
    try testing.expectEqual(Mode.auto, q.mode);
    try testing.expect(q.limit == null);
    const e = defaultOf(struct { m: Tag, l: Length, s: []const u8 });
    try testing.expectEqual(Tag.a, e.m);
    try testing.expect(e.l == .auto);
    try testing.expectEqualStrings("", e.s);
}

test "setPresentDefault makes optionals present with the payload default" {
    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try setPresentDefault(root, base, "palette");
    try testing.expect(p.palette != null);
    try testing.expectEqual(Color.black, p.palette.?.accents[2]);
    try setPresentDefault(root, base, "limit");
    try testing.expectEqual(@as(?u32, 0), p.limit);
}

test "path errors" {
    var p: Probe = .{ .palette = .{ .bg = Color.black, .fg = Color.white } };
    const root, const base = rootOf(&p);
    try testing.expectError(error.UnknownField, get(root, base, "bogus"));
    try testing.expectError(error.UnknownField, get(root, base, "palette.nope"));
    try testing.expectError(error.BadPath, get(root, base, ""));
    try testing.expectError(error.BadPath, get(root, base, "count..x"));
    try testing.expectError(error.BadPath, get(root, base, "count.x")); // a leaf has no fields
    try testing.expectError(error.BadPath, get(root, base, "tint[1]")); // not an array
}

test "dirty categories come from dirty_map; unlisted fields need layout and paint" {
    const t = typeOf(Probe);
    const count = t.field("count").?.dirty;
    try testing.expect(count.layout and !count.paint);
    const tint = t.field("tint").?.dirty;
    try testing.expect(tint.paint and !tint.layout);
    const ratio = t.field("ratio").?.dirty;
    try testing.expect(ratio.layout and ratio.paint);
    const top = try topField(t, "palette.accents[1].r");
    try testing.expectEqualStrings("palette", top.name);
    try testing.expectError(error.UnknownField, topField(t, "zzz.x"));
}

test "metadata comes from the ui decl; read-only fields refuse writes" {
    const t = typeOf(Probe);
    const count = t.field("count").?.meta;
    try testing.expectEqualStrings("How many", count.label.?);
    try testing.expectEqual(@as(?f64, 1), count.min);
    try testing.expectEqual(@as(?f64, 9), count.max);
    try testing.expectEqualStrings("between one and nine", count.tooltip.?);
    try testing.expectEqual(@as(?f64, 0.25), t.field("ratio").?.meta.step);
    try testing.expectEqualStrings("Look", t.field("ratio").?.meta.group.?);
    try testing.expect(t.field("note").?.meta.multiline);
    try testing.expect(t.field("signed").?.meta.label == null);

    var p: Probe = .{};
    const root, const base = rootOf(&p);
    try testing.expectError(error.ReadOnly, set(root, base, "flag", .{ .bool = true }, &test_env));
    try testing.expect(!p.flag);
}

test "display names humanize snake_case unless labeled" {
    var buf: [32]u8 = undefined;
    const t = typeOf(Probe);
    try testing.expectEqualStrings("How many", t.field("count").?.displayName(&buf));
    try testing.expectEqualStrings("On event", t.field("on_event").?.displayName(&buf));
    try testing.expectEqualStrings("Tint", t.field("tint").?.displayName(&buf));
}

test "schemas are comptime constants: the same type gives the same descriptor" {
    try testing.expect(typeOf(Probe) == typeOf(Probe));
    try testing.expect(typeOf(Color) == typeOf(Color));
    try testing.expect(typeOf(Probe).field("tint").?.type == typeOf(Color));
}
